def filter_api_calls(
    logp_with_result: np.ndarray,
    logp_call_only: np.ndarray,
    logp_no_call: np.ndarray,
    tau_filter: float,
) -> tuple[np.ndarray, np.ndarray]:
    """Return an ordered keep mask and one finite margin per proposed call."""

    for arr in [logp_with_result, logp_call_only, logp_no_call]:
        if not isinstance(arr, np.ndarray) or arr.ndim != 2:
            raise ValueError("Each input must be a 2D numpy array")
        if arr.size == 0 or arr.shape[0] == 0 or arr.shape[1] == 0:
            raise ValueError("Empty arrays not allowed")
        if not np.all(np.isfinite(arr)):
            raise ValueError("Non-finite values not allowed")
        if np.any(arr > 0):
            raise ValueError("Positive values not allowed")

    if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
        raise ValueError("Shape mismatch")

    if isinstance(tau_filter, bool):
        raise ValueError("Boolean threshold invalid")
    if not np.isfinite(tau_filter) or tau_filter < 0:
        raise ValueError("tau_filter must be finite nonnegative")

    n, H = logp_with_result.shape

    w_raw = np.array([max(0, 1 - 0.2 * t) for t in range(H)])
    w_sum = np.sum(w_raw)
    if w_sum == 0:
        w = np.zeros(H)
    else:
        w = w_raw / w_sum

    S_result = logp_with_result @ w
    S_no_call = logp_no_call @ w

    margin = S_result - S_no_call
    keep = margin > tau_filter

    return keep, margin
